  p.className = 'token-pill' + (MS.token ? ' ok' : ''); t.textContent = MS.token ? 'Token ready' : 'No token — sign in'; $('#sbMode').textContent = 'SharePoint · ' + (c.siteUrl.split('/').pop() || '');
