  try { if (DB.isSP() && location.protocol === 'file:') throw new Error('Opened as a local file — SharePoint sign-in is not possible here. Click “Use demo data on this computer”, or open the page from https:// or http://localhost.'); if (DB.isSP() && !MS.shared()) await MS.getToken(true); await Auth.login($('#loginUser').value, $('#loginPw').value); Activity.quiet = true; enterApp(); setTimeout(() => { Activity.quiet = false; Activity.add('🔓', 'Signed in'); }, 1500); }
